+        console.log(
+          `Migrated ${result.migrated} session(s) from .kspec/sessions/ to .kspec-sessions/.`,
+        );
+        for (const id of result.migratedIds) {
+          console.log(`  + ${id}`);
+        }
+      }
+
+      if (result.skipped > 0) {
+        console.log(
+          `Skipped ${result.skipped} session(s) (already exist in .kspec-sessions/).`,
