+ * @returns Path to legacy sessions directory, or null if specDir is not available
+ */
+export function getLegacySessionsDir(
+  specDir: string | undefined,
+): string | null {
+  if (!specDir) return null;
+  return path.join(specDir, "sessions");
+}
+
+/**
