+  const metadata = {
+    id: sessionId,
+    agent_type: opts.agentType ?? "claude-code",
+    status: opts.status ?? "completed",
+    started_at: opts.startedAt ?? "2026-03-01T10:00:00.000Z",
+    ended_at: opts.endedAt ?? "2026-03-01T11:00:00.000Z",
