+  await createTestSession(dir, sessionId);
+  const eventsPath = path.join(dir, sessionId, "events.jsonl");
+  const lines = events.map((e, i) =>
+    JSON.stringify({
+      seq: i + 1,
+      ts: Date.now() + i * 1000,
+      type: e.type,
+      session_id: sessionId,
+      data: e.data ?? {},
+    }),
+  );
+  await fs.writeFile(eventsPath, lines.join("\n") + "\n");
