+
+async function createTempDirs(): Promise<void> {
+  tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "kspec-legacy-test-"));
+  primaryDir = path.join(tempDir, ".kspec-sessions");
+  specDir = path.join(tempDir, ".kspec");
